ALTER TABLE "SystemControl" ADD COLUMN "billingCheckoutEnabled" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "BillingSubscription" ADD COLUMN "cancelRequestedAt" TIMESTAMP(3);
CREATE TABLE "BillingRateLimit" (
  "id" UUID NOT NULL,
  "userId" TEXT NOT NULL,
  "operation" TEXT NOT NULL,
  "minuteBucket" TIMESTAMP(3) NOT NULL,
  "requestCount" INTEGER NOT NULL DEFAULT 1,
  CONSTRAINT "BillingRateLimit_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "BillingRateLimit_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT "BillingRateLimit_operation_check" CHECK ("operation" IN ('checkout','portal','cancel','status')),
  CONSTRAINT "BillingRateLimit_count_check" CHECK ("requestCount" > 0),
  CONSTRAINT "BillingRateLimit_minute_check" CHECK (date_trunc('minute', "minuteBucket") = "minuteBucket")
);
CREATE UNIQUE INDEX "BillingRateLimit_userId_operation_minuteBucket_key" ON "BillingRateLimit"("userId", "operation", "minuteBucket");
CREATE INDEX "BillingRateLimit_minuteBucket_idx" ON "BillingRateLimit"("minuteBucket");
